class SubmitLoanRequestModule_AutoGenerated {
  /*find a loan request with provided request id, if the loan request is not exist, create a new loan request with provided info and save it, then the current loan request is it*/
  enterLoanInformation(
    requestid: number,
    name: string,
    loanamount: number,
    loanpurpose: string,
    income: number,
    phonenumber: number,
    postaladdress: string,
    zipcode: number,
    email: string,
    workreferences: string,
    creditreferences: string,
    checkingaccountnumber: number,
    securitynumber: number,
  ): boolean {
    /*Definition Start*/
    let foundLoanRequest: LoanRequest = l({
      logic: () =>
        getRepository(LoanRequest).find(
          (o: any) =>
            l({
              logic: () => o.RequestID === requestid,
              description: "o.RequestID=requestid",
            }).build().pass,
        ),
      description: "LoanRequest.allInstance()->any(o|o.RequestID=requestid)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsTypeOf(requestid, Integer),
        description: "requestid.oclIsTypeOf(Integer)",
      })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(loanamount, Real),
          description: "loanamount.oclIsTypeOf(Real)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newLoan: LoanRequest;
    return l()
      .if({
        logic: () =>
          l({
            logic: () => StandardOPs.oclIsUndefined(foundLoanRequest),
            description: "foundLoanRequest.oclIsUndefined()",
          }),
        description: "foundLoanRequest.oclIsUndefined()",
        then: l({
          execute: () => (newLoan = new LoanRequest()),
          description: "newLoan.oclIsNew()",
        })
          .and({
            execute: () => (newLoan.RequestID = requestid),
            description: "newLoan.RequestID=requestid",
          })
          .and({
            execute: () => (newLoan.Name = name),
            description: "newLoan.Name=name",
          })
          .and({
            execute: () => (newLoan.LoanAmount = loanamount),
            description: "newLoan.LoanAmount=loanamount",
          })
          .and({
            execute: () => (newLoan.LoanPurpose = loanpurpose),
            description: "newLoan.LoanPurpose=loanpurpose",
          })
          .and({
            execute: () => (newLoan.Income = income),
            description: "newLoan.Income=income",
          })
          .and({
            execute: () => (newLoan.PhoneNumber = phonenumber),
            description: "newLoan.PhoneNumber=phonenumber",
          })
          .and({
            execute: () => (newLoan.PostalAddress = postaladdress),
            description: "newLoan.PostalAddress=postaladdress",
          })
          .and({
            execute: () => (newLoan.ZipCode = zipcode),
            description: "newLoan.ZipCode=zipcode",
          })
          .and({
            execute: () => (newLoan.Email = email),
            description: "newLoan.Email=email",
          })
          .and({
            execute: () => (newLoan.WorkReferences = workreferences),
            description: "newLoan.WorkReferences=workreferences",
          })
          .and({
            execute: () => (newLoan.CreditReferences = creditreferences),
            description: "newLoan.CreditReferences=creditreferences",
          })
          .and({
            execute: () =>
              (newLoan.CheckingAccountNumber = checkingaccountnumber),
            description: "newLoan.CheckingAccountNumber=checkingaccountnumber",
          })
          .and({
            execute: () => (newLoan.SecurityNumber = securitynumber),
            description: "newLoan.SecurityNumber=securitynumber",
          })
          .and({
            execute: () => getRepository(LoanRequest).push(newLoan),
            description: "LoanRequest.allInstance()->includes(newLoan)",
          })
          .and({
            execute: () => (this.CurrentLoanRequest = newLoan),
            description: "self.CurrentLoanRequest=newLoan",
          })
          .and({
            execute: () => true,
            description: "result=true",
          }),
        else: l({
          execute: () => (this.CurrentLoanRequest = foundLoanRequest),
          description: "self.CurrentLoanRequest=foundLoanRequest",
        }).and({
          execute: () => true,
          description: "result=true",
        }),
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { SubmitLoanRequestModule_AutoGenerated };

